 public void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putInt("tab",tab);b.putString("detail",detail);b.putString("importTrip",importTrip);}
 protected void onResume(){super.onResume();visible=true;app.listeners.add(changed);refresh();if(replaying){ui.removeCallbacks(tick);ui.post(tick);}for(long delay:new long[]{0,2000,5000,12000})ui.postDelayed(scan,delay);}
