 void showPage(){body.removeAllViews();map=null;seek=null;recordPanel=null;panelSignature="";visibleTrip=null;heading.setText(detail!=null?"旅程详情":new String[]{"旅迹","回忆","设置"}[tab]);for(int i=0;i<nav.getChildCount();i++)nav.getChildAt(i).setBackgroundColor(i==tab?0xFFEAF2FF:Color.WHITE);if(detail!=null||tab==0)showRoute();else if(tab==1)showMemories();else showSettings();}
 void refresh(){if(!visible)return;if(app.error!=null){String error=app.error;app.error=null;new AlertDialog.Builder(this).setTitle("需要处理一下").setMessage(error).setPositiveButton("知道了",null).show();}if(map!=null){Models.Trip t=detail!=null?app.state.trip(detail):app.state.active();String id=t==null?null:t.id;if(!Objects.equals(id,visibleTrip)){stopReplay();showPage();return;}if(t!=null)map.data(app.state.points(t.id),app.state.photos(t.id),app.state.diaries(t.id));if(status!=null)status.setText(app.message);String sig=t==null?"none:"+app.ready:t.id+":"+t.status+":"+t.title+":"+t.favorite+":"+app.state.photos(t.id).size()+":"+app.state.diaries(t.id).size();if(!sig.equals(panelSignature))routePanel(t);else if(t!=null&&recordPanel!=null&&recordPanel.getChildAt(0)instanceof TextView)((TextView)recordPanel.getChildAt(0)).setText(t.title+" · "+distance(t.distance)+" · "+stateLabel(t));}
  else if(tab==1){updateMemories();}}
 static String distance(double n){return n<1000?Math.round(n)+" 米":String.format(Locale.CHINA,"%.2f 公里",n/1000);}
